<?php
require dirname(__DIR__).'/dashboard/private/state.php';
function check(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
$s=initial_state();$j=add_job($s,['docket'=>'25-735','argument_date'=>'2026-10-05','audio_url'=>'https://www.supremecourt.gov/a.mp3','pdf_url'=>'https://www.supremecourt.gov/t.pdf']);$id=$j['id'];$s['jobs'][$id]['stages']['assemble']=['status'=>'complete','result'=>['video_uri'=>'gs://bucket/final.mp4','sha256'=>str_repeat('a',64),'verification'=>'mp4_header']];$s['jobs'][$id]['stages']['render']=['status'=>'complete','tasks'=>[['result'=>['video_uri'=>'chunk-0','sha256'=>'kept','preview_uri'=>'kept-preview']],['result'=>['video_uri'=>'chunk-1']]]];
$c=worker_update($s,['op'=>'chunk_cleanup_claim','job'=>$id],'dispatcher');check(worker_update($s,['op'=>'chunk_cleanup_claim','job'=>$id],'dispatcher')===null,'Two cleaners owned one recording');check(!str_contains(json_encode(public_state($s)),$c['cleanup']['lease']),'Cleanup lease leaked');
$r=['op'=>'chunk_cleanup_result','job'=>$id,'lease'=>$c['cleanup']['lease'],'final_uri'=>'gs://bucket/final.mp4','indices'=>[0],'error'=>null];worker_update($s,$r,'dispatcher');check($s['jobs'][$id]['chunk_cleanup']['status']==='pending','Partial cleanup was completed prematurely');$c=worker_update($s,['op'=>'chunk_cleanup_claim','job'=>$id],'dispatcher');$r['lease']=$c['cleanup']['lease'];$r['indices']=[1];worker_update($s,$r,'dispatcher');check($s['jobs'][$id]['chunk_cleanup']['status']==='complete','Completed cleanup did not persist');check($s['jobs'][$id]['stages']['render']['tasks'][0]['result']['sha256']==='kept'&&$s['jobs'][$id]['stages']['render']['tasks'][0]['result']['preview_uri']==='kept-preview','Receipt or preview lost');check(worker_update($s,['op'=>'chunk_cleanup_claim','job'=>$id],'dispatcher')===null,'Completed cleanup ran again');
echo "Chunk cleanup state checks passed: fencing, resume, receipt retention and completion.\n";
